import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"日知手帖","description":"以观察、摘录、反思和行动回顾组织日常记录，保留不同日知手帖版本和体例的核对空间。","frontmatter":{"title":"日知手帖","description":"以观察、摘录、反思和行动回顾组织日常记录，保留不同日知手帖版本和体例的核对空间。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 个人成长、心理学与健康生活 · 心智与习惯","summary":"以观察、摘录、反思和行动回顾组织日常记录，保留不同日知手帖版本和体例的核对空间。","status":"active","related":[{"title":"高效能人士的七个习惯","link":"/life/personal/books/growth/seven-habits","kind":"书籍导读","scope":"general","audience":"general"},{"title":"哈佛大学性格自修课","link":"/life/personal/books/growth/harvard-character","kind":"书籍导读","scope":"general","audience":"general"},{"title":"当时忍住就好了","link":"/life/personal/books/growth/emotional-control","kind":"书籍导读","scope":"general","audience":"general"},{"title":"正面管教","link":"/life/personal/books/growth/positive-discipline","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"正面管教","link":"/life/personal/books/growth/positive-discipline"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"正面管教","link":"/life/personal/books/growth/positive-discipline"},"next":false},"headers":[],"relativePath":"life/personal/books/growth/daily-notebook.md","filePath":"life/personal/books/growth/daily-notebook.md"}'),i={name:"life/personal/books/growth/daily-notebook.md"};function l(n,e,d,s,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="日知手帖" tabindex="-1">日知手帖 <a class="header-anchor" href="#日知手帖" aria-label="Permalink to &quot;日知手帖&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：个人成长、心理学与健康生活 → 心智与习惯。</strong> 用户书单将它用于日常记录与反思。本页据此把阅读重点放在如何把一闪而过的感受、见闻和问题保存为以后能够理解、检索与回顾的记录。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《日知手帖》：作者或主编待确认。</strong> 本次按完整题名查找，尚未取得能够对应书单的可靠出版记录，不能确认它是出版物、年度手帖还是个人记录名称，也不擅自替换成《日和手帖》或“知日”系列。作者履历、出版社与权威性目前均无法评价。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>以下只针对日常记录主题：适合想保存观察、阅读问题和行动回顾的读者。如果期待系统的日记写作课程，当前信息不足以判断本书是否适合，需先核对出版物体例。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>目前没有作者、年份、出版社或 ISBN，无法判断它属于随笔、阅读手账、年度手帖还是其他体例。<strong>版本待确认；以下为本站主题导读，不是原书目录。</strong> 若实物以日期或栏目组织，而没有传统章节，应按其实际体例补充，不能人为编造章目。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>阅读与记录重点</th><th>示例问题</th></tr></thead><tbody><tr><td>观察</td><td>保存具体事实、场景和细节，减少抽象评语。</td><td>今天真正看见、听见或完成了什么？</td></tr><tr><td>摘录</td><td>为引用保留书名、作者、位置及自己的理解。</td><td>为什么留下这段话，它与哪个问题有关？</td></tr><tr><td>提问</td><td>把困惑转为能够继续查证的问题。</td><td>哪个判断尚无依据，需要什么信息？</td></tr><tr><td>反思</td><td>区分事件、当时的解释和事后认识。</td><td>我的判断发生了什么变化，为什么？</td></tr><tr><td>行动</td><td>将感想变成小而具体的尝试。</td><td>接下来一周可以试做哪一件事？</td></tr><tr><td>回顾</td><td>定期比较重复主题和已经变化的认识。</td><td>哪些问题一直出现，哪些其实已经解决？</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 记录不必每天都深刻，也不必追求连续打卡的完整外观。真正重要的是留下当时无法重新获得的细节，以及能让未来的自己明白“为什么这样想”的背景。</p><p>手帖的价值还来自回读。没有回顾，笔记容易变成信息堆积；定期从记录中提取问题、行动和变化，才能让它参与日常判断。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 值得留下的记录，不只是发生了什么，还有当时为什么这样理解。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 可把一页笔记分成具体事实、当时解释、待查问题和下一步，一周后补一行变化。这是本站给出的记录实验，不声称来自原书；可实践的收获是让回顾看到依据和变化，而不只重复情绪。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>尚未取得文本，无法评价原书章节、语言与编排质量。主题导读可以提供记录起点，却不能代表此书内容。<strong>推荐语：</strong> 先保存一周可回读的具体记录；是否推荐本书，待作者、ISBN与目录确认后判断。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://search.worldcat.org/search?q=%E6%97%A5%E7%9F%A5%E6%89%8B%E5%B8%96" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：核对作者、年份与出版物体例，当前未确认原书目录。</li><li>对手帖类出版物，还应核对封面年份、版权页与实际栏目名称，避免把不同年度的内容混为一谈。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const g=t(i,[["render",l]]);export{b as __pageData,g as default};
